class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        left = [0] * n
        st = []
        for i, h in enumerate(maxHeights):
            while st and maxHeights[st[-1]] > h:
                st.pop()
            p = st[-1] if st else -1
            left[i] = h * (i - p) + (left[p] if p >= 0 else 0)
            st.append(i)
        right = [0] * n
        st = []
        for i in range(n - 1, -1, -1):
            h = maxHeights[i]
            while st and maxHeights[st[-1]] > h:
                st.pop()
            p = st[-1] if st else n
            right[i] = h * (p - i) + (right[p] if p < n else 0)
            st.append(i)
        return max(left[i] + right[i] - maxHeights[i] for i in range(n))

