class Solution {
public:
    long long maximumSumOfHeights(vector<int>& maxHeights) {
        int n = maxHeights.size();
        vector<long long> left(n), right(n);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            long long h = maxHeights[i];
            while (!st.empty() && maxHeights[st.back()] > h) st.pop_back();
            int p = st.empty() ? -1 : st.back();
            left[i] = h * (i - p) + (p >= 0 ? left[p] : 0);
            st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            long long h = maxHeights[i];
            while (!st.empty() && maxHeights[st.back()] > h) st.pop_back();
            int p = st.empty() ? n : st.back();
            right[i] = h * (p - i) + (p < n ? right[p] : 0);
            st.push_back(i);
        }
        long long ans = 0;
        for (int i = 0; i < n; i++)
            ans = max(ans, left[i] + right[i] - maxHeights[i]);
        return ans;
    }
};

