class Solution {
    public long maximumSumOfHeights(List<Integer> maxHeights) {
        int n = maxHeights.size();
        long[] left = new long[n], right = new long[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            long h = maxHeights.get(i);
            while (!st.isEmpty() && maxHeights.get(st.peek()) > h) st.pop();
            int p = st.isEmpty() ? -1 : st.peek();
            left[i] = h * (i - p) + (p >= 0 ? left[p] : 0);
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            long h = maxHeights.get(i);
            while (!st.isEmpty() && maxHeights.get(st.peek()) > h) st.pop();
            int p = st.isEmpty() ? n : st.peek();
            right[i] = h * (p - i) + (p < n ? right[p] : 0);
            st.push(i);
        }
        long ans = 0;
        for (int i = 0; i < n; i++)
            ans = Math.max(ans, left[i] + right[i] - maxHeights.get(i));
        return ans;
    }
}

