class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        ans = 0
        for i in range(n):
            total = cur = maxHeights[i]
            for j in range(i - 1, -1, -1):
                cur = min(cur, maxHeights[j])
                total += cur
            cur = maxHeights[i]
            for j in range(i + 1, n):
                cur = min(cur, maxHeights[j])
                total += cur
            ans = max(ans, total)
        return ans

